<script setup lang="ts">
import {reactive,computed,watch} from 'vue';
import {riskPosition,type RiskInput} from '../lib/risk';
const props=defineProps<{instrumentId:string;referencePrice?:number|null;entry?:number|null;stop?:number|null;holdings?:boolean}>();
const form=reactive<RiskInput>({instrumentId:props.instrumentId,equity:0,cash:0,entry:0,stop:0,current:props.referencePrice||0,riskPct:1,accountRiskPct:5,otherRisk:0,positionCapPct:20,existingQuantity:0,sellableQuantity:0,cost:0,commissionPct:.03,minimumCommission:5,sellTaxPct:.05,slippagePct:.1});
watch(()=>props.instrumentId,id=>{form.instrumentId=id;form.entry=0;form.stop=0;form.current=props.referencePrice||0;form.existingQuantity=0;form.sellableQuantity=0;form.cost=0;});
watch(()=>props.referencePrice,value=>{form.current=value||0;});
function useReference(){if(props.entry)form.entry=props.entry;if(props.stop)form.stop=props.stop;}
const calculated=computed(()=>{try{return {value:riskPosition(form),error:''};}catch(e){return {value:null,error:e instanceof Error?e.message:'请检查输入'};}});
const money=(n:number|null|undefined)=>n===null||n===undefined?'—':n.toLocaleString('zh-CN',{maximumFractionDigits:2,minimumFractionDigits:2});
</script>
<template>
  <section class="panel risk-calculator"><div class="panel-heading"><h2>{{holdings?'持仓风险与加仓预算':'风险仓位计算器'}}</h2><button v-if="entry&&stop" class="secondary" @click="useReference">填入条件参考价</button></div><p class="subtle calculator-note">资金与持仓只在当前页面计算，不上传或持久保存。比例与费用均可修改。</p>
    <form @submit.prevent class="risk-form">
      <label>账户总权益（元）<input v-model.number="form.equity" type="number" min="0" step="100" placeholder="请输入真实权益"/></label><label>可用现金（元）<input v-model.number="form.cash" type="number" min="0" step="100"/></label>
      <label>{{holdings?'计划加仓价（元，不加仓填0）':'计划买入价（元）'}}<input v-model.number="form.entry" type="number" min="0" step="0.01"/></label><label>计划止损价（元）<input v-model.number="form.stop" type="number" min="0" step="0.01"/></label>
      <label>单股风险上限（%）<input v-model.number="form.riskPct" type="number" min="0" max="100" step="0.1"/></label><label>单股仓位上限（%）<input v-model.number="form.positionCapPct" type="number" min="0" max="100" step="1"/></label>
      <label>账户总风险上限（%）<input v-model.number="form.accountRiskPct" type="number" min="0" max="100" step="0.1"/></label><label>其他持仓止损风险（元）<input v-model.number="form.otherRisk" type="number" min="0" step="100"/></label>
      <template v-if="holdings"><label>已有股数<input v-model.number="form.existingQuantity" type="number" min="0" step="1"/></label><label>今天可卖股数<input v-model.number="form.sellableQuantity" type="number" min="0" :max="form.existingQuantity" step="1"/></label><label>持仓成本（元/股）<input v-model.number="form.cost" type="number" min="0" step="0.01"/></label><label>当前参考价（元）<input v-model.number="form.current" type="number" min="0" step="0.01"/></label></template>
      <details class="fee-settings"><summary>手续费与滑点假设</summary><div class="risk-form"><label>佣金（%/单边）<input v-model.number="form.commissionPct" type="number" min="0" max="5" step="0.001"/></label><label>最低佣金（元/单边）<input v-model.number="form.minimumCommission" type="number" min="0" step="1"/></label><label>卖出税费假设（%）<input v-model.number="form.sellTaxPct" type="number" min="0" max="5" step="0.001"/></label><label>单边滑点（%）<input v-model.number="form.slippagePct" type="number" min="0" max="10" step="0.01"/></label></div><p class="subtle">估算双边佣金及卖出税费；过户费等可计入佣金假设，请按实际券商费率调整。单次计算上限10万股，是研究限制。</p></details>
    </form>
    <p v-if="!calculated.value" class="calculator-empty">{{calculated.error}}</p>
    <template v-else><div class="risk-output"><div><span>预算允许新增</span><strong>{{calculated.value.quantity.toLocaleString()}}<small> 股</small></strong></div><div><span>含费用占用现金</span><strong>{{money(calculated.value.cashRequired)}}</strong></div><div><span>预估止损损失</span><strong class="bull">{{money(calculated.value.plannedLoss)}}</strong></div><div><span>新增风险预算</span><strong>{{money(calculated.value.riskBudget)}}</strong></div></div><p v-if="calculated.value.reasons.length" class="risk-warning">{{calculated.value.reasons.join('；')}}</p><p class="subtle">{{calculated.value.lot.label}} · 新增后单股仓位 {{calculated.value.positionPct.toFixed(2)}}% · 组合估算止损风险 {{money(calculated.value.accountRisk)}} 元</p>
      <div v-if="calculated.value.holding" class="holding-output"><h3>当前持仓测算</h3><dl><div><dt>市值</dt><dd>{{money(calculated.value.holding.marketValue)}} 元</dd></div><div><dt>浮动盈亏（费用前）</dt><dd>{{money(calculated.value.holding.unrealized)}} 元</dd></div><div><dt>估算保本卖价</dt><dd>{{money(calculated.value.holding.breakEven)}} 元</dd></div><div><dt>参考止损处预计盈亏</dt><dd>{{money(calculated.value.holding.estimatedStopPnl)}} 元</dd></div><div><dt>今天可卖 / 锁定数量</dt><dd>{{calculated.value.holding.sellable}} / {{calculated.value.holding.locked}} 股</dd></div></dl></div>
    </template>
    <p class="subtle calculator-note">可买数量同时受现金、已有持仓风险、单股仓位和账户总风险限制。新增股票受T+1约束；涨跌停、停牌和跳空可能使实际损失超过预算，当前未核验实时可成交性。</p>
  </section>
</template>
<style scoped>.risk-calculator>.panel-heading{flex-wrap:wrap}.calculator-note{margin:14px 0;line-height:1.9}.risk-form{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-top:22px}.risk-form label{display:grid;gap:9px;font-size:12px;min-width:0}.risk-form input{width:100%}.fee-settings{grid-column:1/-1;color:var(--muted);font-size:12px}.fee-settings summary{cursor:pointer}.fee-settings .risk-form{margin:16px 0}.risk-output{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;border-block:1px solid var(--border);padding:24px 0;margin:24px 0 16px}.risk-output span{display:block;color:var(--muted);font-size:12px}.risk-output strong{display:block;margin-top:10px;font-size:25px}.risk-output small{font-size:13px}.calculator-empty{margin:24px 0 12px;padding:18px;background:var(--surface-alt);color:var(--muted)}.risk-warning{color:var(--bull);margin:12px 0;font-size:13px}.holding-output{border-top:1px solid var(--border);margin-top:24px;padding-top:20px}.holding-output dl{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.holding-output dt{color:var(--muted);font-size:12px}.holding-output dd{margin:10px 0;font-weight:600}@media(max-width:1000px){.risk-form{grid-template-columns:repeat(2,1fr)}.risk-output{grid-template-columns:repeat(2,1fr)}}@media(max-width:550px){.risk-calculator{padding:20px}.risk-form{gap:14px}.risk-output strong{font-size:22px}.holding-output dl{grid-template-columns:1fr 1fr}.risk-form label{font-size:11px}}</style>
